//! `$AuthoredKeyWitness` maps its keys as optional: one generated byte in every
//! projection's shared helper preamble, on top of the latest successors.

use super::receipt::authenticate_successor_receipt;

pub(super) fn slots(predecessor: &'static str) -> &'static str {
    let successor = include_str!(
        "../fixtures/public-instance-options-api-slots/successor-optional-jsx-witness/projection-record.txt"
    );
    authenticate_successor_receipt(
        include_str!(
            "../fixtures/public-instance-options-api-slots/successor-optional-jsx-witness/receipt.json"
        ),
        "b6bb8675a8a89031c3ff106edd91e187460f43898ddc9040b9c14e4099de07bd",
        13975,
        predecessor,
        successor,
    );
    successor
}

